import { tags } from "typia";

/**
 * Operational alert record generated by the shipping analytics engine to flag
 * performance anomalies.
 *
 * This schema represents a single alert instance triggered by an automated
 * system that monitors key logistics metrics. It is designed to notify
 * administrators and logistics managers of situations that may significantly
 * impact customer satisfaction, operational efficiency, or financial
 * performance.
 *
 * The alert contains sufficient detail to identify the nature of the problem
 * (type), its severity (severity), where it's occurring
 * (carrier_code/region_code), and how serious it is (current_value vs
 * threshold_value). The recommended_action field provides initial guidance to
 * the operations team.
 *
 * This object is not tied to any single database table but is generated by the
 * analytics engine through complex pattern detection across multiple entities,
 * including shipping_mall_delivery_events, shopping_mall_order_shipments,
 * shopping_mall_carriers, and shopping_mall_orders.
 *
 * All alerts are persisted for audit trail, trend analysis, and failure mode
 * identification. The resolved field allows for integration with ticketing
 * systems and operational workflows.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallAlert = {
  /**
   * Unique identifier for this alert instance.
   *
   * A system-generated UUID that uniquely identifies this alert record. Used
   * for tracking, de-duplication, and reference in audit logs and
   * notification systems.
   */
  alert_id: string & tags.Format<"uuid">;

  /**
   * The exact moment when the alert condition was detected and triggered.
   *
   * Based on the system's timestamp at the time of analytics engine
   * evaluation, using the same precision as other system timestamps. Critical
   * for correlating alerts with actual operational events and for time-series
   * analysis of alert patterns.
   */
  timestamp: string & tags.Format<"date-time">;

  /**
   * The urgency level assigned to this alert based on the impact on logistics
   * operations and customer satisfaction.
   *
   * Severity levels are defined as follows:
   *
   * - Low: Minor deviation from expected performance with minimal impact
   * - Medium: Noticeable impact on operational efficiency but no immediate
   *   customer service disruption
   * - High: Significant degradation in shipping performance with potential for
   *   customer complaints
   * - Critical: Systemic failure or carrier-wide issue requiring immediate
   *   intervention
   *
   * Determined by automated scoring based on deviation thresholds from
   * historical baselines.
   */
  severity: "low" | "medium" | "high" | "critical";

  /**
   * Categorical classification of the specific triggering condition.
   *
   * Each value represents a distinct failure mode detected by the analytics
   * engine:
   *
   * - Carrier_failure_rate_exceeded: Current failure rate exceeds configured
   *   threshold for a carrier
   * - Delivery_delay_spike: Median delivery time increased significantly
   *   compared to historical baseline for a region/carrier
   * - Regional_shipment_blockage: Unusually high number of shipments with no
   *   tracking updates for >48hrs in a region
   * - Cost_variance_alert: Shipping costs significantly deviate from benchmark
   *   against historical trends
   * - Reliability_score_drop: DICE correlation score exceeds allowed threshold
   * - Notification_failure: Internal alert notification system failed to
   *   deliver message to stakeholders
   *
   * The type field enables automated routing and categorization of alerts for
   * appropriate response teams.
   */
  type:
    | "carrier_failure_rate_exceeded"
    | "delivery_delay_spike"
    | "regional_shipment_blockage"
    | "cost_variance_alert"
    | "reliability_score_drop"
    | "notification_failure";

  /**
   * A human-readable explanation of the alert condition.
   *
   * Provides context to the operational team about what specific metric
   * triggered the alert and why it's significant.
   *
   * Example: "Carrier DHL_EUROPE has exceeded its 10% failure rate threshold:
   * current rate 12.3%. Past week: 5.1%. "
   *
   * Generated by template-based logic using the specific metric values and
   * thresholds.
   */
  message: string;

  /**
   * The carrier identifier associated with this alert, if applicable.
   *
   * Matches the carrier_code field in the shopping_mall_carriers table. Only
   * populated when the alert pertains to a specific carrier's performance.
   *
   * For non-carrier alerts (e.g., regional, system-wide), this field will be
   * null.
   */
  carrier_code?: string | undefined;

  /**
   * The geographic region identifier associated with this alert, if
   * applicable.
   *
   * Matches the region_code field used in shopping_mall_regions and
   * shopping_mall_order_addresses. Only populated when the alert is
   * region-specific.
   *
   * For carrier-specific or system-wide alerts, this field will be null.
   */
  region_code?: string | undefined;

  /**
   * The configured threshold value that was exceeded to trigger this alert.
   *
   * For example, if alert type is "carrier_failure_rate_exceeded",
   * threshold_value might be 10.0 (meaning 10%).
   *
   * Used to verify the accuracy of the alert trigger and for historical trend
   * analysis of threshold adjustments.
   */
  threshold_value: number;

  /**
   * The actual measured value that triggered the alert.
   *
   * For example, if alert type is "carrier_failure_rate_exceeded",
   * current_value might be 12.3 (meaning 12.3% failure rate).
   *
   * Provides immediate context about the severity of the deviation and allows
   * for automated incident response logic to act.
   */
  current_value: number;

  /**
   * Time period over which the detected metric was calculated.
   *
   * Indicates the reporting period used to determine the current value and
   * compare against the threshold.
   *
   * Format is ISO 8601 duration (e.g., "P7D" for 7 days, "P1M" for 1 month).
   * Critical for understanding the context of the measurement.
   */
  observation_window: string;

  /**
   * Estimated number of orders impacted by this alert condition.
   *
   * Calculated by counting shopping_mall_orders that have associated
   * shopping_mall_order_shipments matching the failed carrier or region.
   *
   * Used for impact assessment and prioritization of response actions.
   */
  affected_orders?: (number & tags.Type<"int32"> & tags.Minimum<0>) | undefined;

  /**
   * Suggested operational response for the logistics team.
   *
   * Generated based on alert type and severity. "Recommended" does not imply
   * mandatory action.
   *
   * Examples:
   *
   * - "Contact DHL support to investigate current shipping failures and request
   *   new SLA adjustments"
   * - "Reroute shipments in Central region to alternative carrier for next 48
   *   hours"
   * - "Review billing configuration for Doogan Express as costs have exceeded
   *   budget by 27%"
   */
  recommended_action?: string | undefined;

  /**
   * Indicates whether this alert has been acknowledged and resolved by the
   * operations team.
   *
   * Initial value is false when alert is first triggered. Set to true when
   * operations team manually confirms resolution via admin interface.
   *
   * Used to distinguish between active and historical alerts in reporting
   * dashboards.
   */
  resolved?: boolean | undefined;

  /**
   * The system component or process that generated this alert.
   *
   * Values are system-defined identifiers, not user names. Example:
   * "shipping-analytics-engine-v2"
   *
   * Tracks the source of alert generation for debugging and audit trail
   * purposes.
   */
  created_by: string;
};
